			hint = [=[Отнесите срочное послание от Великого Подъемника на Заставу Вольного Ветра.]=],
			text = [=[Храбрец у Великого Подъемника сообщил, что {link:centaurs}кентавр{/link}ы возобновили набеги. Для одного из караванов весть пришла слишком поздно: кентавры Галак уже напали на него и убили всех {link:tauren}таурен{/link}ов, которые с ним ехали. Долгорог назвал это злодеянием и поклялся, что оно не останется безнаказанным. Он послал всех воинов, готовых сражаться, на лагерь кентавров Галак к северу от заставы.]=],
		},
		{
			title = "Тайные письма",
			hint = [=[Узнайте, что клан Зловещего Тотема скрывает на Пике Темного Облака.]=],
			text = [=[За несколько недель видели, как клан Зловещего Тотема посетили трое чужаков неизвестного происхождения. Долгорог узнал, что каждый оставил послание в отдельном сундуке на Пике Темного Облака, и велел их забрать. Письма были написаны некоему Агашаму, и подписали их трое, называвшие себя Вестниками. В них говорилось о союзе, о котором другие племена {link:tauren}таурен{/link}ов никогда не должны узнать, о полном повиновении и об агентах из {link:lordaeron}Лордерона{/link}, которые вскоре встретятся с посланцами адресата. Долгорог прочел их и назвал эти вести грозными. Он начал готовиться ко всему, что может случиться.]=],
		},
	},
	mentions = {
		{
			text = [=[Послание на Заставу Вольного Ветра, которое принес гонец храбреца Лунного Рога]=],
		},
		{ text = "Усмирить {link:centaurs}кентавр{/link}ов" },
		{ text = "Слежка за кланом Зловещего Тотема" },
		{
