		},
		{
			title = "Тревожный ответ",
			hint = "Убейте змею Арикару и вернитесь на Заставу Белого Плеса.",
			text = [=[{link:magatha-grimtotem}Старшая Ведунья{/link} предупредила, что {link:arikara}Арикара{/link}, возможно, выслеживает верховного вождя {link:cairne-bloodhoof}Кэрна Кровавое Копыто{/link}, разгневанная тем, что слишком многое в древних преданиях {link:tauren}таурен{/link}ов изменилось. Когда змея была убита, Мотега покачал головой. Ему казалось бессмысленным, что Арикара стала бы охотиться на верховного вождя. Но он не захотел сказать, что Магата ошиблась. Она, сказал он, самая могучая из них.]=],
		},
	},
	mentions = {
		{ text = "Дорога домой" },
