Translate("ruRU", "wizlo-bearingshiner", {
	title = "Визло Блестящий Подшипник",
	subtitle = "Уцелевший из каравана",
	found = "Застава Белого Плеса",
	hint = [=[Поговорите с гоблином-механиком, который пережил набег кентавров.]=],
	allegiance = "Гоблин-механик",
	aliases = { "Визло" },
	sections = {
		{
			title = "Обзор",
			text = [=[Визло Блестящий Подшипник — гоблин-механик, единственный уцелевший из каравана, на который {link:centaurs}кентавр{/link}ы напали возле Лагеря Э'Ток. Кентавры Галак забрали все, что могли унести. Его лучшее изобретение они не взяли только потому, что оно висит на шее пантеры в клетке, которой боятся даже кентавры. Ключ от клетки до сих пор у него.]=],
		},
		{
			title = "Значение",
			text = [=[Потеря, которую понес Визло, — малая история войны между {link:centaurs}кентавр{/link}ами Галак и всеми остальными. Он хочет вернуть свое устройство, хотя признает, что сам еще не знает, что оно делает.]=],
		},
	},
	mentions = {
		{ text = "Гиперконденсаторное устройство" },
	},
	bonds = {
		{ id = "kanati-greycloud", name = "Канати Серое Облако", note = "дает ему приют на Заставе Белого Плеса" },
	},
})

Translate("ruRU", "arnak-grimtotem", {
	title = "Арнак Зловещий Тотем",
	subtitle = "Изгой",
	found = "Утесы возле Пика Темного Облака",
	hint = [=[Сразитесь с изгоем, которого разыскивают на Заставе Вольного Ветра.]=],
	allegiance = "Клан Зловещего Тотема (изгой)",
	aliases = { "Арнак" },
	sections = {
		{
			title = "Обзор",
			text = [=[Арнак — изгой из {link:grimtotem-clan}клана Зловещего Тотема{/link}, которого разыскивают на Заставе Вольного Ветра за убийство и похищение. Он попросил {link:tauren}таурен{/link}ку Лакоту Песнь Ветра стать его парой, и она отказала ему. В ту же ночь он вернулся и забрал ее силой. Ее брат попытался остановить его, и Арнак убил его. Затем он унес пленницу на {link:darkcloud-pinnacle}Пик Темного Облака{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Преступления изгоя возбудили гнев всей Заставы Вольного Ветра. {link:cliffwatcher-longhorn}Страж утесов Долгорог{/link} опасался, что его никогда не удастся предать суду, и говорил, что от вестей о его делах у него закипает кровь.]=],
		},
	},
	mentions = {
		{ text = "Разыскивается: Арнак Зловещий Тотем" },
		{ text = "{link:nak}Нак{/link}онец на свободе" },
	},
	bonds = {
		{ id = "lakota-windsong", name = "Лакота Песнь Ветра", note = "тауренка, которую он похитил" },
		{ id = "cliffwatcher-longhorn", name = "страж утесов Долгорог", note = "назначил за него награду" },
	},
})

Translate("ruRU", "lakota-windsong", {
	title = "Лакота Песнь Ветра",
	subtitle = "Пленница Пика Темного Облака",
	found = "Пик Темного Облака",
	hint = [=[Найдите тауренку, которую держат в плену на Пике Темного Облака.]=],
	allegiance = "Орда",
	aliases = { "Лакота" },
	sections = {
		{
			title = "Обзор",
			text = [=[Лакота Песнь Ветра отказала изгою, когда {link:arnak-grimtotem}Арнак{/link} попросил ее стать его парой. Он вернулся ночью и похитил ее, а ее брата, который бился, чтобы остановить его, убил. Ее держали среди игл Пика Темного Облака; она оплакивала брата и тосковала по Заставе Вольного Ветра, где ее ждала {link:thalia-amberhide}Талия Янтарная Шкура{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Побег пленницы с Пика завершил историю преступлений, которые совершил {link:arnak-grimtotem}Арнак{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Наконец на свободе",
			hint = "Выведите тауренку Лакоту с Пика Темного Облака.",
			text = [=[Путь с Пика шел через собственные владения клана Зловещего Тотема. Лакота спустилась с игл живой и добралась до Заставы Вольного Ветра, где {link:thalia-amberhide}Талия{/link} ни на миг не переставала ее ждать. Там она говорила о храбрости тех, кто привел ее домой.]=],
		},
	},
	mentions = {
		{ text = "{link:nak}Нак{/link}онец на свободе" },
	},
	bonds = {
		{ id = "thalia-amberhide", name = "Талия Янтарная Шкура", note = "ждала ее" },
		{ id = "arnak-grimtotem", name = "Арнак Зловещий Тотем", note = "ее похититель" },
	},
})

Translate("ruRU", "arikara", {
	title = "Арикара",
	subtitle = "Змея отмщения",
	found = "Священный огонь Пика Темного Облака",
	hint = [=[Разожгите священный огонь там, где клан Зловещего Тотема хоронит своих мертвых.]=],
	allegiance = "Нет",
	sections = {
		{
			title = "Обзор",
			text = [=[Арикара — змея из легенд {link:tauren}таурен{/link}ов, создание, рожденное, как говорят, лишь для того, чтобы мстить тем, кто совершил гнусные деяния. Священный огонь жизни на Пике Темного Облака, спавший долгие годы, может вызвать ее. В эти дни ее яйцо нашли в змеиной норе в Иглах, и детеныш вылупился на Заставе Вольного Ветра.]=],
		},
		{
			title = "Значение",
			text = [=[Арикара — легенда, которая ожила. {link:magatha-grimtotem}Магата Зловещий Тотем{/link} предупредила, что змея, возможно, выслеживает верховного вождя {link:cairne-bloodhoof}Кэрна Кровавое Копыто{/link}, разгневанная переменами в древних преданиях {link:tauren}таурен{/link}ов. Некоторым на Заставе Белого Плеса это предостережение было трудно понять.]=],
		},
	},
	mentions = {
		{ text = "Чужое яйцо" },
		{ text = "Дикая змея" },
		{ text = "Священный огонь" },
		{ text = "Арикара" },
	},
	bonds = {
		{ id = "magatha-grimtotem", name = "Магата Зловещий Тотем", note = "говорила о ней" },
		{ id = "motega-firemane", name = "Мотега Огненная Грива", note = "знал легенду о ней" },
		{ id = "hagar-lightninghoof", name = "Хагар Копыто Молнии", note = "видел ее детеныша" },
	},
})

Translate("ruRU", "dorn-plainstalker", {
	title = "Дорн Степной Ловец",
	subtitle = "Испытатель молодых",
	found = "Уединенная высота к северо-востоку от Заставы Вольного Ветра",
	hint = [=[Отыщите таурена, который испытывает молодых на уединенной высоте над Иглами.]=],
	allegiance = "Орда",
	aliases = { "Дорн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дорн Степной Ловец живет один на высоте над Иглами, вдали от суеты Заставы Вольного Ветра. Он считает своим долгом готовить молодых из всех племен к опасностям, которые встретятся им, когда они покинут безопасный дом. Он испытывает их в трех вещах: в духе, в теле и в разуме. Те, кто проходит испытания, возвращаются сильнее. Те, кто не проходит, говорит он, узнают, как на самом деле {link:ogres}огр{/link}омен мир.]=],
		},
		{
			title = "Значение",
			text = [=[Дорн — наставник старого склада. Ему нет дела до того, из какого племени пришел воин, а только до того, готов ли этот воин. Его испытания связывают между собой нескольких мудрецов Орды в {link:kalimdor}Калимдор{/link}е и за его пределами.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он испытывает веру, выносливость, силу и знания молодых.
• Он посылает их против матриарха гарпий из Логова Легкоперых и против элементаля {link:rok-alim-the-pounder}Рок'Алим{/link}а.
• Он отправляет их дальше, в {link:stonetalon-mountains}Когтистые горы{/link}, где испытание знаний дает шаман {link:braug-dimspirit}Брауг Тусклый Дух{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О жизни наставника и о том, как давно он живет на своей высоте, написано мало. Его племя не названо.]=],
		},
	},
	chapters = {
		{
			title = "Прыжок веры",
			hint = "Докажите свою веру на высоте, где живет Дорн.",
			text = [=[Первое испытание самое странное. Дорн просит молодых шагнуть с дощатого настила его высоты в пустоту, без обещания, что они останутся живы. Вера, учит он, значит больше, чем многие думают. Не всегда важно, во что именно веришь, но важно верить во что-то.]=],
		},
		{
			title = "Тело и сила",
			hint = "Пройдите испытания выносливости и силы.",
			text = [=[Ради испытания тела Дорн посылает молодых в {link:roguefeather-den}Логово Легкоперых{/link} — испортить припасы гарпий и встретить их матриарха, Гренку Кровавый Визг, когда она явится в ярости. Ради испытания силы он посылает их против элементаля, который задержался в Иглах с эпохи Древних богов: это {link:rok-alim-the-pounder}Рок'Алим{/link}.]=],
		},
		{
			title = "Последний переход",
			hint = "Завершите испытание знаний и вернитесь к наставнику Дорну.",
			text = [=[Испытание знаний дает не он. Оно идет через шамана {link:braug-dimspirit}Брауг{/link}а Тусклого Духа в Когтистых горах и дальше, к ученым далеко от Игл. Когда молодые наконец возвращаются, Дорн смотрит на них так, словно с их первого прыжка минуло много лун, и говорит им, что их разум, тело и дух сильны.]=],
		},
	},
	mentions = {
		{ text = "Испытание веры" },
		{ text = "Испытание выносливости" },
		{ text = "Испытание силы" },
		{
			text = [=[Испытание знаний, дорога к шаману {link:braug-dimspirit}Брауг{/link}у Тусклому Духу]=],
		},
		{ text = "Последний переход" },
	},
	bonds = {
		{ id = "grenka-bloodscreech", name = "Гренка Кровавый Визг", note = "испытание выносливости" },
		{ id = "rok-alim-the-pounder", name = "Рок'Алим Молотильщик", note = "испытание силы" },
		{ id = "prate-cloudseer", name = "Прейт Провидица Облаков", note = "живет возле его высоты" },
		{ id = "braug-dimspirit", name = "Брауг Тусклый Дух", note = "дает испытание знаний" },
	},
})

Translate("ruRU", "prate-cloudseer", {
	title = "Прейт Провидица Облаков",
	subtitle = "Шаманка воздуха",
	found = "Возле высоты, где живет Дорн Степной Ловец",
	hint = [=[Отыщите шаманку воздуха, которая живет рядом с наставником Дорном Степным Ловцом.]=],
	allegiance = "Орда · Шаманы",
	aliases = { "Прейт" },
	sections = {
		{
			title = "Обзор",
			text = [=[Прейт Провидица Облаков — шаманка, которая держится в стороне от поселений Игл, возле высоты, где живет {link:dorn-plainstalker}Дорн Степной Ловец{/link}. Она изучает ветры {link:kalimdor}Калимдор{/link}а. Шаманов, готовых воззвать к духам воздуха, посылают искать ее далеко на восток каньона, и она учит их тому, что им нужно для начала.]=],
		},
		{
			title = "Значение",
