		},
	},
	mentions = {
		{ text = "Зов воздуха" },
		{ text = "Зов воздуха" },
	},
	bonds = {
		{ id = "dorn-plainstalker", name = "Дорн Степной Ловец", note = "ее сосед на высотах" },
	},
})

Translate("ruRU", "grenka-bloodscreech", {
	title = "Гренка Кровавый Визг",
	subtitle = "Матриарх Логова Легкоперых",
	found = "Глубины Логова Легкоперых",
	hint = [=[Испортите припасы гарпий в Логове Легкоперых и дождитесь их матриарха.]=],
