	sections = {
		{
			title = "Обзор",
			text = [=[Гренка Кровавый Визг правит {link:harpies}гарпиями{/link} Каньона Визга, которые гнездятся в Логове Легкоперых. Она не выходит навстречу чужакам. Она является, когда ее логово грабят, и является в ярости. {link:dorn-plainstalker}Дорн Степной Ловец{/link} назвал ее испытанием выносливости, ибо никто не может встретиться с ней, не пережив сперва гнев всей ее стаи.]=],
