	},
})

Translate("ruRU", "rok-alim-the-pounder", {
	title = "Рок'Алим Молотильщик",
	subtitle = "Элементаль древней эпохи",
	found = "К западу от Заставы Вольного Ветра",
	hint = [=[Сразитесь с древним элементалем, который бродит по западу Игл.]=],
	allegiance = "Нет",
	aliases = { "Рок'Алим" },
	sections = {
		{
			title = "Обзор",
			text = [=[В эпоху Древних богов элементали наполняли большую часть мира и были привязаны к нему силой богов, которым служили. Когда Древние боги были низвергнуты, большинство элементалей исчезло из мира, и теперь они возвращаются лишь на зов могучих магов. Немногие оказались достаточно сильны, чтобы остаться сами. Рок'Алим — один из них. {link:centaurs}Кентавры{/link} зовут его Молотильщиком — за гром, с которым падают его кулаки.]=],
		},
	},
	mentions = {
		{ text = "Испытание силы" },
	},
	bonds = {
		{ id = "dorn-plainstalker", name = "Дорн Степной Ловец", note = "назвал его испытанием" },
	},
})

Translate("ruRU", "steelsnap", {
	title = "Стальной Щелкун",
	subtitle = "Тиран гиен",
	found = "Северо-западные склоны, возле Лагеря Э'Ток",
