	sections = {
		{
			title = "Обзор",
			text = [=[Стальной Щелкун — гиена Игл, которая притягивает к себе других гиен и ведет их сеять страх и резню среди более кротких зверей. Охотники-{link:tauren}таурен{/link}ы охотятся на эту гиену не ради пищи и не ради чести. Они охотятся на нее потому, что это создание вне благословения {red:earth-mother}Матери-Земли{/red}, и земля без него чище.]=],
