	},
})

Translate("ruRU", "moktar-krin", {
	title = "Моктар Крин",
	subtitle = "Предводитель разбитого боевого отряда",
	found = "Северная граница Мерцающей равнины",
	hint = [=[Найдите орка, который держит военный лагерь на границе Мерцающей равнины.]=],
	allegiance = "Орда · Оргриммар",
	aliases = { "Моктар" },
	sections = {
		{
			title = "Обзор",
			text = [=[Моктар Крин повел боевой отряд Орды, чтобы выгнать {link:dwarves}дворф{/link}ов {link:explorers-league}Лиги исследователей{/link} с Мерцающей равнины. Дворфы погибли, но во время боя из пещеры в карьере вырвался рой насекомых и убил больше половины его воинов. Теперь он держит лагерь на границе Равнины с отрядом, который слишком изранен, чтобы идти в поход. Он ждет приказов из {link:orgrimmar}Оргриммара{/link}, от своего командира Белгрома Камнемолота, и следит за югом.]=],
		},
		{
			title = "Значение",
			text = [=[Моктар первым в Орде столкнулся с силитидами в Иглах и поплатился за это. Его донесение, доставленное на {link:the-crossroads}Перекресток{/link}, где его принял Корран, помогло Орде начать понимать этих насекомых.]=],
		},
	},
	chapters = {
		{
			title = "Рой растет",
			hint = "Отбросьте насекомых Карьера Ржавой Кувалды.",
			text = [=[Белгром хотел, чтобы насекомых загнали обратно в те глубины, откуда они явились. Воины, которых вел Моктар, не могли сделать это одни. С помощью путников, ехавших на гонки, рой проредили, а панцири, снятые с убитых, отправили на изучение: их ждал Корран.]=],
		},
	},
	mentions = {
		{ text = "Рой растет" },
		{ text = "Рой растет" },
		{ text = "Части роя" },
	},
	bonds = {
		{ id = "korran", name = "Корран", note = "изучает насекомых на Перекрестке" },
		{ id = "belgrom-rockmaul", name = "Белгром Камнемолот", note = "его командир в Оргриммаре" },
	},
})

Translate("ruRU", "pozzik", {
	title = "Поззик",
	subtitle = "Главный механик гоблинов-гонщиков",
	found = "Мастерские гоблинов на Виражах на Миражах",
	hint = [=[Поговорите с гоблином-механиком в мастерских гоблинов на Виражах на Миражах.]=],
	allegiance = "Картель Хитрая Шестеренка · Гоночная команда гоблинов",
	sections = {
		{
			title = "Обзор",
			text = [=[Поззик некогда был одним из самых уважаемых механиков Нижней Шахты. Он оставил Союз Механиков, чтобы работать над гоночными машинами, и первым делом придумал модели с двумя двигателями, на которых команда гоблинов ездит до сих пор. Теперь он руководит ее механиками на Мерцающей равнине. Он взвешивает каждый болт и каждую кость, потому что в гонках важна каждая унция.]=],
		},
		{
			title = "Значение",
			text = [=[Поззик — мозг команды гоблинов, и он проигрывает. {link:gnomes}Гномы{/link} его догоняют, и он пойдет почти на все, чтобы не отстать: обратится к гоблинским баронам и строителям, которые его поддерживают деньгами, а если придется, то и обворует соперников.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он придумал гоблинские гоночные машины с двумя двигателями.
• Он строит рамы из полых костей стервятников Равнины.
• Он искал новый регулятор топлива через двух покровителей: это {link:gazlowe}Газлоу{/link} из {link:ratchet}Кабестана{/link} и барон {link:baron-revilgaz}Ревилгаз{/link} из {link:booty-bay}Пиратской бухты{/link}.
• По его воле были украдены чертежи, которые составил Риззл Медноштиф, и из них он узнал тайну индурия.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О годах, которые Поззик провел в Нижней Шахте, и о том, почему он ее оставил, написано мало.]=],
		},
	},
	chapters = {
		{
			title = "Гоблинские покровители",
			hint = [=[Выясните, что сталось с регулятором топлива, который был обещан механику Поззику.]=],
			text = [=[{link:gazlowe}Газлоу{/link} обещал новый регулятор топлива, и тот так и не прибыл. След вел из {link:ratchet}Кабестан{/link}а на причалы Пиратской бухты и к барону {link:baron-revilgaz}Ревилгаз{/link}у; он признал, что его люди не сумели найти чертежи. Чертежи лежали в доме бригадира {link:venture-company}Торговой Компании{/link} в {link:stranglethorn-vale}Тернистой долине{/link}, который поставил новый регулятор на свои крошшеры. Когда чертежи наконец попали в мастерские гоблинов, это оказались всего лишь рисунки. Поззик все равно был доволен, ибо теперь мог улучшить конструкцию с самого основания.]=],
		},
		{
			title = "Не отставать",
			hint = "Помогите механику Поззику узнать тайну скорости гномов.",
			text = [=[Машины {link:gnomes}гном{/link}ов стали быстрее, но каждая конструкция, которую Поззик мог разглядеть, была такой же, как прежде. Он заключил, что гномы нашли новый материал. Пока Замек отвлекал внимание, чертежи были похищены из-под самого носа их хозяина; им был Риззл Медноштиф. В них говорилось об индурии — руде из раскопок {link:dwarves}дворф{/link}ов в {link:uldaman}Ульдамане{/link}, которая выдерживает сильный жар, а ее кусок служил пресс-папье.]=],
		},
	},
	mentions = {
		{ text = "Облегчение груза" },
		{ text = "Гоблинские покровители" },
		{ text = "Гоблинские покровители, чертежи привезены домой" },
		{ text = "Восемнадцатый пилот" },
