			title = "Обзор",
			text = [=[Раззерик — пилот гоночной команды гоблинов, восемнадцатый, кто занимает это место. Когда-то он бегал с поручениями по мастерским. Теперь он водит машину, и после того как {link:pozzik}Поззик{/link} заканчивает каждую гоночную машину, Раззерик ослабляет управление, обдирает раму и добавляет огня. Поззик поставил ему под сиденье ведро с песком. Раззерик не может этого простить.]=],
		},
		{
			title = "Значение",
			text = [=[Раззерик — причина того, что гоблины побеждают, когда побеждают, и причина того, что они горят, когда горят. Его собственный инженер в {link:gadgetzan}Прибамбасск{/link}е вслух задавался вопросом, выйдет ли толк из девятнадцатого пилота.]=],
		},
	},
	chapters = {
		{
			title = "Безопасность прежде всего",
			hint = [=[Добейтесь, чтобы с ускорителя, который заказал Раззерик, сняли предохранитель.]=],
			text = [=[Раззерик заказал ускоритель на сефории в мастерской Гизмориум в {link:gadgetzan}Прибамбасск{/link}е, в {link:tanaris}Танарисе{/link}; делал его инженер {link:shreev}Шрив{/link}. Дирижабль, который вез ускоритель, разбился в {link:dustwallow-marsh}Пылевых топях{/link}, а когда ускоритель наконец нашли, на нем все еще стоял предохранитель. Раззерик отослал его обратно. Шрив, который и так уже сделал его куда опаснее, чем было разумно, снял предохранитель.]=],
		},
	},
	mentions = {
		{ text = "Восемнадцатый пилот" },
		{ text = "Доработки Раззерика" },
		{ text = "Безопасность прежде всего" },
		{ text = "Безопасность прежде всего, ускоритель возвращен" },
	},
	bonds = {
		{ id = "pozzik", name = "Поззик", note = "его механик" },
	},
})

Translate("ruRU", "fizzle-brassbolts", {
