Translate("ruRU", "kravel-koalbeard", {
	title = "Крейвел Угольная Борода",
	subtitle = "Делец Виражей на Миражах",
	found = "Рядом с мастерскими гномов на Виражах на Миражах",
	hint = [=[Поговорите с дельцом, который скупает обломки и продает услуги на Виражах.]=],
	allegiance = "Собственный кошелек",
	aliases = { "Крейвел" },
	sections = {
		{
			title = "Обзор",
			text = [=[Крейвел Угольная Борода сделал своим ремеслом доставать людям то, что им нужно, и брать по пути свою долю. Он скупает обломки разбитых гоночных машин и продает их обратно той команде, которая заплатит. Он выполняет заказы {link:gnomes}гном{/link}ов и оставляет себе понемногу от каждого. Он считает, что в чужой беде всегда есть прибыль, и говорит об этом открыто.]=],
		},
		{
			title = "Значение",
			text = [=[Крейвел — изнанка Виражей на Миражах. Через него соперничество гоблинов и {link:gnomes}гном{/link}ов становится торговлей тайнами, взятками и элем с дурманом, а его рука дотягивается от {link:ratchet}Кабестан{/link}а до Пиратской бухты.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он скупает лом разбитых гоночных машин с Равнины.
• Он взял небольшую часть из заказа {link:gnomes}гном{/link}ов на детали, прежде чем доставить его.
• Он узнал тайну гоблина-пилота Назза Кипятка и намеревался продать свое молчание.
• Он послал ящик особых боеприпасов в Тернистую долину, где его ждал давний покупатель, {link:hemet-nesingwary}Хеминг Эрнестуэй{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[О том, откуда пришел Крейвел и кто оплачивает его счет, написано мало.]=],
		},
	},
	chapters = {
		{
			title = "Тайна пилота",
			hint = "Узнайте правду о гоблине-пилоте Наззе Кипятке.",
			text = [=[До дельца дошел слух, что гоблин-пилот Назз Кипяток не всегда носил это имя. Крейвел послал к собирателю слухов из Пиратской бухты; это был {link:krazek}Кразек{/link}, который расплатился услугами и редкой бутылкой эльфийского вина, чтобы узнать причину. Кразек счел тайну слишком опасной, чтобы пользоваться ею самому. Крейвел так не считал. Он рассчитывал, что Назз заплатит небольшое состояние, лишь бы она осталась скрытой.]=],
		},
		{
			title = "Крепкий эль для дураков",
			hint = [=[Помогите дельцу Крейвелу испытать замысел против механиков команд.]=],
			text = [=[Вместе с Крэнком {link:crank-fizzlebub}Физзлбаб{/link}ом, гоблином из Пиратской бухты, Крейвел состряпал замысел. Физзлбаб смешал крепкий эль со снадобьем, которым тролль {link:zanzil-the-outcast}Занзил{/link} поит своих безмозглых слуг, и дрожжи в нем взбесились. {link:nak}Нак{/link}ануне гонки Крейвел дал этот эль, названный «Дурацкое Крепкое», механикам одной из команд и сделал ставку. Это сработало, и он надеялся на большее.]=],
		},
	},
	mentions = {
		{ text = "Детали ракетной машины" },
		{ text = "Начальник порта Диззивиг" },
		{ text = "Детали для Крейвела" },
		{ text = "Доставка {link:gnomes}гном{/link}ам" },
		{ text = "Собиратель слухов" },
		{ text = "Слухи для Крейвела" },
		{ text = "Обратно в Пиратскую бухту" },
		{ text = "Напоить {link:gnomes}гном{/link}ов" },
		{ text = "Напоить гоблинов" },
		{ text = "Доложить {link:crank-fizzlebub}Физзлбаб{/link}у" },
		{ text = "{link:hemet-nesingwary}Хеминг Эрнестуэй{/link}" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Физзл Медноштиф", note = "заказчик, которого он обсчитал" },
		{ id = "crank-fizzlebub", name = "Крэнк Физзлбаб", note = "его сообщник в кознях" },
		{ id = "krazek", name = "Кразек", note = "продал ему тайну" },
		{ id = "hemet-nesingwary", name = "Хеминг Эрнестуэй", note = "давний покупатель" },
	},
})

